type ERABDataForwardingItem struct { // [{'type': 'E-RAB-ID', 'name': 'e-RAB-ID'}, {'type': 'TransportLayerAddress', 'name': 'dL-transportLayerAddress', 'optional': True}, {'type': 'GTP-TEID', 'name': 'dL-gTP-TEID', 'optional': True}, {'type': 'TransportLayerAddress', 'name': 'uL-TransportLayerAddress', 'optional': True}, {'type': 'GTP-TEID', 'name': 'uL-GTP-TEID', 'optional': True}, {'type': 'ProtocolExtensionContainer', 'actual-parameters': ['E-RABDataForwardingItem-ExtIEs'], 'name': 'iE-Extensions', 'optional': True}, None]
    ERABID ERABID
    DLtransportLayerAddress *TransportLayerAddress
    DLgTPTEID *GTPTEID
    ULTransportLayerAddress *TransportLayerAddress
    ULGTPTEID *GTPTEID
    IEExtensions *ERABDataForwardingItemExtIEs
}

func (self * ERABDataForwardingItem) Unpack(stream *Stream) {
    dLtransportLayerAddress_flag := 0x00000002
    dLgTPTEID_flag := 0x00000004
    uLTransportLayerAddress_flag := 0x00000008
    uLGTPTEID_flag := 0x00000010
    iEExtensions_flag := 0x00000020
    const ext_flag = 0x00000001
    _flags := 0
    _extflags := 0
    _ecount := 0
    _flags = stream.get_flags(6)
    self.ERABID.Unpack(stream)// p8
    if (dLtransportLayerAddress_flag & _flags) == dLtransportLayerAddress_flag { //cond2
        self.DLtransportLayerAddress = &TransportLayerAddress{}//7{'type': 'TransportLayerAddress', 'name': 'dL-transportLayerAddress', 'optional': True}
        self.DLtransportLayerAddress.Unpack(stream)// p8
    }
    if (dLgTPTEID_flag & _flags) == dLgTPTEID_flag { //cond2
        self.DLgTPTEID = &GTPTEID{}//7{'type': 'GTP-TEID', 'name': 'dL-gTP-TEID', 'optional': True}
        self.DLgTPTEID.Unpack(stream)// p8
    }
    if (uLTransportLayerAddress_flag & _flags) == uLTransportLayerAddress_flag { //cond2
        self.ULTransportLayerAddress = &TransportLayerAddress{}//7{'type': 'TransportLayerAddress', 'name': 'uL-TransportLayerAddress', 'optional': True}
        self.ULTransportLayerAddress.Unpack(stream)// p8
    }
    if (uLGTPTEID_flag & _flags) == uLGTPTEID_flag { //cond2
        self.ULGTPTEID = &GTPTEID{}//7{'type': 'GTP-TEID', 'name': 'uL-GTP-TEID', 'optional': True}
        self.ULGTPTEID.Unpack(stream)// p8
    }
    if (iEExtensions_flag & _flags) == iEExtensions_flag { //cond2
        self.IEExtensions = &ERABDataForwardingItemExtIEs{}//7{'type': 'ProtocolExtensionContainer', 'actual-parameters': ['E-RABDataForwardingItem-ExtIEs'], 'name': 'iE-Extensions', 'optional': True}
        IEExtensions := ProtocolExtensionContainer {table_ERABDataForwardingItemExtIEs, order_ERABDataForwardingItemExtIEs} // p3
        IEExtensions.Unpack(stream, &self.IEExtensions) // p3
    }
    stream.handle_unknown_ext(_ecount, _extflags, 0, _flags)
    return
}

func (self * ERABDataForwardingItem) Pack(stream *Stream) {
    const dLtransportLayerAddress_flag uint = 0x00000002
    const dLgTPTEID_flag uint = 0x00000004
    const uLTransportLayerAddress_flag uint = 0x00000008
    const uLGTPTEID_flag uint = 0x00000010
    const iEExtensions_flag uint = 0x00000020
    const ext_flag int = 0x00000001
    _flagReserve := stream.reserve_flags(6)
    var _extReserve uint32 = 0
    var _extPresent bool = false
    var _flags uint = 0
    var _extflags uint = 0
    self.ERABID.Pack(stream)
    if self.DLtransportLayerAddress != nil { 
        _flags |= dLtransportLayerAddress_flag
        self.DLtransportLayerAddress.Pack(stream)
    }//end of optional
    if self.DLgTPTEID != nil { 
        _flags |= dLgTPTEID_flag
        self.DLgTPTEID.Pack(stream)
    }//end of optional
    if self.ULTransportLayerAddress != nil { 
        _flags |= uLTransportLayerAddress_flag
        self.ULTransportLayerAddress.Pack(stream)
    }//end of optional
    if self.ULGTPTEID != nil { 
        _flags |= uLGTPTEID_flag
        self.ULGTPTEID.Pack(stream)
    }//end of optional
    if self.IEExtensions != nil { 
        _flags |= iEExtensions_flag
        IEExtensions := &ProtocolExtensionContainer {table_ERABDataForwardingItemExtIEs, order_ERABDataForwardingItemExtIEs} // p3
        IEExtensions.Pack(stream, &self.IEExtensions)
    }//end of optional
    if _extPresent { stream.set_flags(_extflags, _extReserve, 0) }
    stream.set_flags(_flags, _flagReserve, 6)
}//end

