func (self *IMSI) Pack(st *Stream) {
    if len(self.Value) < 3 || len(self.Value) > 8 {
        log.Error ("Invalid len in IMSI")
        return
}
    st.format_olen((len(self.Value))-3, 3)
    st.formatf_OctString(self.Value, 0)
}
