func (self *MDTMode)Unpack(stream *Stream) {
    //coptions := []string{"immediateMDT","loggedMDT","mDTMode-Extension"}
    choice := stream.get_choice(1, 1, 2)
    choice_len := 0
    choice_loc := 0
    if choice >= 2 {
        choice_len = stream.parse_len(0)
        choice_loc = stream.get_location()
        log.Info("Extension choice option [%d] len %d in MDTMode\n", choice, choice_len)
    }
    if choice == 0 { //ch1
        self.ImmediateMDT = &ImmediateMDT{}//cho6
        self.ImmediateMDT.Unpack(stream)
    } else if choice == 1 { //ch2
        self.LoggedMDT = &LoggedMDT{}//cho6
        self.LoggedMDT.Unpack(stream)
    } else if choice == 2 { //ch2
        self.MDTModeExtension = &MDTModeExtension{}//cho6
        self.MDTModeExtension.Unpack(stream)
    }//end of if else

    if choice >= 2 {
        stream.set_location(choice_loc, choice_len)
    }
}
func (self * MDTMode) Pack(stream *Stream) {
    if self.ImmediateMDT != nil {
        stream.set_choice(0, 1, 1, 2)
        self.ImmediateMDT.Pack(stream)//2
    } else if self.LoggedMDT != nil {
        stream.set_choice(1, 1, 1, 2)
        self.LoggedMDT.Pack(stream)//2
    } else if self.MDTModeExtension != nil {
        stream.set_choice(2, 1, 1, 2)
        lenLoc := stream.reserve_len()
        self.MDTModeExtension.Pack(stream)//2
        stream.set_len(lenLoc)
    }

}
