type TransportInformation struct { // [{'type': 'TransportLayerAddress', 'name': 'transportLayerAddress'}, {'type': 'GTP-TEID', 'name': 'uL-GTP-TEID'}, None]
    TransportLayerAddress TransportLayerAddress
    ULGTPTEID GTPTEID
}

func (self * TransportInformation) Unpack(stream *Stream) {
    const ext_flag = 0x00000001
    _flags := 0
    _extflags := 0
    _ecount := 0
    _flags = stream.get_flags(1)
    self.TransportLayerAddress.Unpack(stream)// p8
    self.ULGTPTEID.Unpack(stream)// p8
    stream.handle_unknown_ext(_ecount, _extflags, 0, _flags)
    return
}

func (self * TransportInformation) Pack(stream *Stream) {
    const ext_flag int = 0x00000001
    _flagReserve := stream.reserve_flags(1)
    var _extReserve uint32 = 0
    var _extPresent bool = false
    var _flags uint = 0
    var _extflags uint = 0
    self.TransportLayerAddress.Pack(stream)
    self.ULGTPTEID.Pack(stream)
    if _extPresent { stream.set_flags(_extflags, _extReserve, 0) }
    stream.set_flags(_flags, _flagReserve, 1)
}//end

type TransportLayerAddress struct {
  Len int
  Value HexBytes
}
func (self *TransportLayerAddress) Unpack(st *Stream){
    self.Len = int(st.parse_blen(9, 1)+1)
    self.Value = st.parsef_BitString(160, int(self.Len))
}
func (self *TransportLayerAddress) Pack(st *Stream) {
    st.format_blen(int(self.Len-1), 9, 1)
    st.formatf_BitString(self.Value, int(self.Len))
}
type TraceActivation struct { // [{'type': 'E-UTRAN-Trace-ID', 'name': 'e-UTRAN-Trace-ID'}, {'type': 'InterfacesToTrace', 'name': 'interfacesToTrace'}, {'type': 'TraceDepth', 'name': 'traceDepth'}, {'type': 'TransportLayerAddress', 'name': 'traceCollectionEntityIPAddress'}, {'type': 'ProtocolExtensionContainer', 'actual-parameters': ['TraceActivation-ExtIEs'], 'name': 'iE-Extensions', 'optional': True}, None]
    EUTRANTraceID EUTRANTraceID
    InterfacesToTrace InterfacesToTrace
    TraceDepth TraceDepth
    TraceCollectionEntityIPAddress TransportLayerAddress
    IEExtensions *TraceActivationExtIEs
}

func (self * TraceActivation) Unpack(stream *Stream) {
    iEExtensions_flag := 0x00000002
    const ext_flag = 0x00000001
    _flags := 0
    _extflags := 0
    _ecount := 0
    _flags = stream.get_flags(2)
    self.EUTRANTraceID.Unpack(stream)// p8
    self.InterfacesToTrace.Unpack(stream)// p8
    self.TraceDepth.Unpack(stream)// p8
    self.TraceCollectionEntityIPAddress.Unpack(stream)// p8
    if (iEExtensions_flag & _flags) == iEExtensions_flag { //cond2
        self.IEExtensions = &TraceActivationExtIEs{}//7{'type': 'ProtocolExtensionContainer', 'actual-parameters': ['TraceActivation-ExtIEs'], 'name': 'iE-Extensions', 'optional': True}
        IEExtensions := ProtocolExtensionContainer {table_TraceActivationExtIEs, order_TraceActivationExtIEs} // p3
        IEExtensions.Unpack(stream, &self.IEExtensions) // p3
    }
    stream.handle_unknown_ext(_ecount, _extflags, 0, _flags)
    return
}

func (self * TraceActivation) Pack(stream *Stream) {
    const iEExtensions_flag uint = 0x00000002
    const ext_flag int = 0x00000001
    _flagReserve := stream.reserve_flags(2)
    var _extReserve uint32 = 0
    var _extPresent bool = false
    var _flags uint = 0
    var _extflags uint = 0
    self.EUTRANTraceID.Pack(stream)
    self.InterfacesToTrace.Pack(stream)
    self.TraceDepth.Pack(stream)
    self.TraceCollectionEntityIPAddress.Pack(stream)
    if self.IEExtensions != nil { 
        _flags |= iEExtensions_flag
        IEExtensions := &ProtocolExtensionContainer {table_TraceActivationExtIEs, order_TraceActivationExtIEs} // p3
        IEExtensions.Pack(stream, &self.IEExtensions)
    }//end of optional
    if _extPresent { stream.set_flags(_extflags, _extReserve, 0) }
    stream.set_flags(_flags, _flagReserve, 2)
}//end

