type UEAppLayerMeasConfig struct { // [{'type': 'OCTET STRING', 'size': [(1, 1000)], 'name': 'containerForAppLayerMeasConfig'}, {'type': 'AreaScopeOfQMC', 'name': 'areaScopeOfQMC'}, {'type': 'ProtocolExtensionContainer', 'actual-parameters': ['UEAppLayerMeasConfig-ExtIEs'], 'name': 'iE-Extensions', 'optional': True}, None]
    ContainerForAppLayerMeasConfig OCTETSTRING
    AreaScopeOfQMC AreaScopeOfQMC
    IEExtensions *UEAppLayerMeasConfigExtIEs
}

func (self * UEAppLayerMeasConfig) Unpack(stream *Stream) {
    iEExtensions_flag := 0x00000002
    const ext_flag = 0x00000001
    _flags := 0
    _extflags := 0
    _ecount := 0
    _flags = stream.get_flags(2)
    var Unpack_containerForAppLayerMeasConfig = func(st *Stream, self *OCTETSTRING) {
        _len := st.parse_len(10)+1
        if _len < 1 || _len > 1000 {
            //fmt.Println( "Invalid len in containerForAppLayerMeasConfig ")
            return
        }
        self.Value = st.parsef_OctString(_len)
    }
    Unpack_containerForAppLayerMeasConfig(stream, &self.ContainerForAppLayerMeasConfig)// p2
    self.AreaScopeOfQMC.Unpack(stream)// p8
    if (iEExtensions_flag & _flags) == iEExtensions_flag { //cond2
        self.IEExtensions = &UEAppLayerMeasConfigExtIEs{}//7{'type': 'ProtocolExtensionContainer', 'actual-parameters': ['UEAppLayerMeasConfig-ExtIEs'], 'name': 'iE-Extensions', 'optional': True}
        IEExtensions := ProtocolExtensionContainer {table_UEAppLayerMeasConfigExtIEs, order_UEAppLayerMeasConfigExtIEs} // p3
        IEExtensions.Unpack(stream, &self.IEExtensions) // p3
    }
    stream.handle_unknown_ext(_ecount, _extflags, 0, _flags)
    return
}

func (self * UEAppLayerMeasConfig) Pack(stream *Stream) {
    const iEExtensions_flag uint = 0x00000002
    const ext_flag int = 0x00000001
    _flagReserve := stream.reserve_flags(2)
    var _extReserve uint32 = 0
    var _extPresent bool = false
    var _flags uint = 0
    var _extflags uint = 0
    var Pack_containerForAppLayerMeasConfig = func(st *Stream, self OCTETSTRING) {
        if len(self.Value) < 1 || len(self.Value) > 1000 {
            log.Error ("Invalid len in containerForAppLayerMeasConfig")
            return
    }
        st.format_olen((len(self.Value))-1, 10)
        st.formatf_OctString(self.Value, 0)
    }
    Pack_containerForAppLayerMeasConfig(stream, self.ContainerForAppLayerMeasConfig) //f2
    self.AreaScopeOfQMC.Pack(stream)
    if self.IEExtensions != nil { 
        _flags |= iEExtensions_flag
        IEExtensions := &ProtocolExtensionContainer {table_UEAppLayerMeasConfigExtIEs, order_UEAppLayerMeasConfigExtIEs} // p3
        IEExtensions.Pack(stream, &self.IEExtensions)
    }//end of optional
    if _extPresent { stream.set_flags(_extflags, _extReserve, 0) }
    stream.set_flags(_flags, _flagReserve, 2)
}//end

